package io.tornado.reporting;import io.tornado.persistence.Direction;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class MixConsensusTest{@Test void appliesStrictMajorityForSizesTwoThroughEight(){assertVote(2,2);assertVote(3,2);assertVote(4,3);assertVote(5,3);assertVote(6,4);assertVote(7,4);assertVote(8,5);}@Test void tiesAndInsufficientVotesAreNotSignals(){assertThat(MixConsensus.decide(2,List.of(Direction.UP,Direction.DOWN)).decisive()).isFalse();assertThat(MixConsensus.decide(4,List.of(Direction.UP,Direction.UP,Direction.DOWN,Direction.DOWN)).decisive()).isFalse();}@Test void neutralVotesDoNotCount(){var result=MixConsensus.decide(3,List.of(Direction.UP,Direction.UP,Direction.NEUTRAL));assertThat(result.direction()).isEqualTo(Direction.UP);assertThat(result.agreement()).isEqualTo(2);}private void assertVote(int size,int required){List<Direction>votes=new ArrayList<>();for(int i=0;i<required;i++)votes.add(Direction.UP);for(int i=required;i<size;i++)votes.add(Direction.DOWN);var result=MixConsensus.decide(size,votes);assertThat(result.direction()).isEqualTo(Direction.UP);assertThat(result.required()).isEqualTo(required);}}
